{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Sampled training separation is strong across categories, but Movies_and_TV is weakest: its mean margin is 1.8996 and negative-over-positive rate is 4.92%, versus 1.67–2.12% elsewhere.",
    "All four categories fail the padding-invariance check. Matched prefix removal reduces margins in every category, suggesting useful historical context, although padding sensitivity confounds these effects."
  ],
  "key_implications": [
    "The model usually ranks positives above sampled negatives; these diagnostics do not establish validation HR@10.",
    "Embedding alignment is modest rather than near complete collapse, with collapse scores of 0.5514–0.6059.",
    "Context-removal results do not establish that cropped training would improve validation performance."
  ],
  "evidence": {
    "headline_metrics": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0492,
      "Electronics:padding_feature_max_abs_error": 0.0023423433303833008,
      "padding_check_tolerance": 0.00001,
      "Electronics:context_removed_only:paired_margin_delta": -1.5118071911009876
    },
    "brief_metric_read": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": "Highest sampled training misranking rate across categories.",
      "Electronics:padding_feature_max_abs_error": "Largest padding discrepancy; exceeds the declared tolerance.",
      "Electronics:context_removed_only:paired_margin_delta": "Largest matched margin loss among rows with actual prefix removal."
    }
  }
}
